66	    /** Every claim on the sheet by the person who made it, each person's newest first. */
67	    @Transactional(readOnly = true)
68	    public Map<Long, List<Claim>> bySheet(String sheetId) {
69	        return claims.findBySheetIdOrderByListedDesc(sheetId).stream()
70	                .collect(Collectors.groupingBy(Claim::getPersonId));
71	    }
72	
73	    @Transactional(readOnly = true)
74	    public List<Claim> forPerson(String sheetId, long personId) {
75	        return claims.findBySheetIdAndPersonIdOrderByListedDesc(sheetId, personId);
76	    }
