78	    /** Add a claim; a date left out takes the sheet's today. Returns the person it belongs to. */
79	    @Transactional
80	    public long add(String sheetId, String user, long personId, BigDecimal amount, LocalDate date, String note) {
81	        return add(sheetId, user, personId, amount, date, note, null);
82	    }
