84	    /**
85	     * Add a claim, a correction naming the number of the claim it corrects; a date left out takes the
86	     * sheet's today. Returns the person it belongs to.
87	     */
88	    @Transactional
89	    public long add(String sheetId, String user, long personId, BigDecimal amount, LocalDate date, String note,
90	            String corrects) {
91	        Person person = people.findByIdAndSheetId(personId, sheetId)
92	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person"));
93	        LocalDate on = date != null ? date : sheets.today(sheetId);
94	        periods.requireOpen(sheetId, on);
95	        requireNotRetired(person, on);
96	        LocalDate correctsDate = requireCorrects(sheetId, personId, amount, corrects);
97	        Rollup.Figures before = rollup.figures(sheetId);
98	        Claim claim = new Claim(sheetId, personId, amount, on, note == null ? "" : note, corrects);
99	        claim.setCorrectsDate(correctsDate);
100	        sheets.load(sheetId, user);
101	        claim.setDueBy(on.plusDays(sheets.settings(sheetId).termsFor(person.gradeOn(on), on)));
102	        log(sheetId, user, claim, person);
103	        claims.saveAndFlush(claim);
104	        events.publishEvent(new ClaimChanged("CLAIM_ADDED", sheetId, user, person.getName(), amount, on, null, null));
105	        rollup.changed(sheetId, user, before);
106	        return personId;
107	    }
108	
109	    /**
110	     * Edit a claim's amount, date and note; only a DRAFT can be edited (an open claim is voided and
111	     * added again instead), and an edit is refused when a closed period contains its date or the new one.
112	     * Returns the person it belongs to.
113	     */
114	    @Transactional
115	    public long edit(String sheetId, String user, long claimId, BigDecimal amount, LocalDate date, String note,
116	            String corrects) {
117	        Claim claim = claims.findByIdAndSheetId(claimId, sheetId)
118	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim"));
119	        LocalDate on = date != null ? date : sheets.today(sheetId);
120	        periods.requireOpen(sheetId, claim.getDate(), on);
121	        if (claim.getStatus() != ClaimStatus.DRAFT) {
122	            throw new ResponseStatusException(HttpStatus.CONFLICT,
123	                    "A " + claim.getStatus() + " claim cannot be edited; void it and add a new one");
124	        }
125	        if (!on.equals(claim.getDate())) {
126	            people.findByIdAndSheetId(claim.getPersonId(), sheetId).ifPresent(p -> requireNotRetired(p, on));
127	        }
128	        LocalDate correctsDate = requireCorrects(sheetId, claim.getPersonId(), amount, corrects);
129	        Rollup.Figures before = rollup.figures(sheetId);
130	        claim.setAmount(amount);
131	        claim.setCorrects(corrects);
132	        claim.setCorrectsDate(correctsDate);
133	        claim.setDate(on);
134	        claim.setNote(note == null ? "" : note);
135	        claims.flush();
136	        String person = people.findByIdAndSheetId(claim.getPersonId(), sheetId).map(Person::getName).orElse("");
137	        events.publishEvent(new ClaimChanged("CLAIM_EDITED", sheetId, user, person, claim.getAmount(),
138	                claim.getDate(), claim.getShownNumber(), null));
139	        rollup.changed(sheetId, user, before);
140	        return claim.getPersonId();
141	    }
142	
143	    /**
144	     * Move a claim to a status; a move its status does not allow, settling by the user who opened
145	     * the claim, or moving a claim dated inside a closed period, is refused and changes nothing. Settling
146	     * by a clerk a claim whose due is above the clerk limit leaves it PENDING.
147	     * Returns the person it belongs to.
148	     */
149	    @Transactional
150	    public long move(String sheetId, String user, long claimId, ClaimStatus next) {
151	        Claim claim = claim(sheetId, claimId);
152	        if (!claim.getStatus().canBecome(next)) {
153	            throw new ResponseStatusException(HttpStatus.CONFLICT,
154	                    "A " + claim.getStatus() + " claim cannot become " + next);
155	        }
156	        if (next == ClaimStatus.SETTLED && user.equals(claim.getOpenedBy())) {
157	            throw new ResponseStatusException(HttpStatus.FORBIDDEN,
158	                    "The user who opened a claim cannot settle it");
159	        }
160	        Rollup.Figures before = rollup.figures(sheetId);
161	        if (next == ClaimStatus.OPEN) {
162	            giveNumber(sheetId, claim);
163	            claim.setOpenedBy(user);
164	        }
165	        String number = claim.getShownNumber();
166	        Person owner = people.findByIdAndSheetId(claim.getPersonId(), sheetId).orElse(null);
167	        String due = null;
168	        if (next == ClaimStatus.SETTLED) {
169	            BigDecimal fixed = dueNow(sheetId, claim, owner);
170	            if (access.canSettle(sheetId, user, fixed)) {
171	                claim.setSettledDue(fixed);
172	                due = fixed == null ? "n/a" : fixed.toPlainString();
173	            } else {
174	                next = ClaimStatus.PENDING;
175	            }
176	        }
177	        claim.setStatus(next);
178	        log(sheetId, user, claim, owner);
179	        claims.flush();
180	        String person = owner == null ? "" : owner.getName();
181	        String event = switch (next) {
182	            case OPEN -> "CLAIM_OPENED";
183	            case PENDING -> "CLAIM_PENDING";
184	            case SETTLED -> "CLAIM_SETTLED";
185	            case VOID -> "CLAIM_VOIDED";
186	            case DRAFT -> throw new IllegalStateException();
187	        };
188	        events.publishEvent(new ClaimChanged(event, sheetId, user, person, claim.getAmount(), claim.getDate(), number, due));
189	        rollup.changed(sheetId, user, before);
190	        return claim.getPersonId();
191	    }
192	
193	    /**
194	     * Approve a PENDING claim, settling it with its due fixed now (its live figure, late charge frozen in).
195	     * Only a steward approves, never the user who opened the claim; a claim not PENDING or dated inside a
196	     * closed period is refused and nothing changes. Returns the person it belongs to.
197	     */
198	    @Transactional
199	    public long approve(String sheetId, String user, long claimId) {
200	        Claim claim = pending(sheetId, user, claimId, "approve", "approved");
201	        if (user.equals(claim.getOpenedBy())) {
202	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "The user who opened a claim cannot approve it");
203	        }
204	        Rollup.Figures before = rollup.figures(sheetId);
205	        Person owner = people.findByIdAndSheetId(claim.getPersonId(), sheetId).orElse(null);
206	        BigDecimal fixed = dueNow(sheetId, claim, owner);
207	        claim.setSettledDue(fixed);
208	        claim.setStatus(ClaimStatus.SETTLED);
209	        log(sheetId, user, claim, owner);
210	        claims.flush();
211	        events.publishEvent(new ClaimChanged("CLAIM_APPROVED", sheetId, user, owner == null ? "" : owner.getName(),
212	                claim.getAmount(), claim.getDate(), claim.getShownNumber(), fixed == null ? "n/a" : fixed.toPlainString()));
213	        rollup.changed(sheetId, user, before);
214	        return claim.getPersonId();
215	    }
216	
217	    /**
218	     * Re-settle a SETTLED claim, fixing its due again at the figure it would have today as an OPEN claim bound
219	     * by no statement (today's rates, grades, floor and late charge), and logging it SETTLED again. Only a
220	     * steward re-settles; a claim not SETTLED or dated inside a closed period is refused and nothing changes.
221	     * Returns the person it belongs to.
222	     */
223	    @Transactional
224	    public long resettle(String sheetId, String user, long claimId) {
225	        Claim claim = claim(sheetId, claimId);
226	        if (claim.getStatus() != ClaimStatus.SETTLED) {
227	            throw new ResponseStatusException(HttpStatus.CONFLICT,
228	                    "A " + claim.getStatus() + " claim cannot be re-settled; only a SETTLED one can");
229	        }
230	        if (access.roleOf(sheetId, user) != Role.STEWARD) {
231	            throw new ResponseStatusException(HttpStatus.CONFLICT, "Only a steward can re-settle a claim");
232	        }
233	        Person owner = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
234	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person"));
235	        Rollup.Figures before = rollup.figures(sheetId);
236	        BigDecimal old = claim.getSettledDue();
237	        BigDecimal fixed = Dues.asOpen(claim, owner::gradeOn, rates.table(sheetId));
238	        claim.setSettledDue(fixed);
239	        claim.logStatus(user, sheets.today(sheetId), fixed);
240	        claims.flush();
241	        events.publishEvent(new ClaimResettled(sheetId, user, owner.getName(), claim.getAmount(), claim.getDate(),
242	                claim.getShownNumber(), old, fixed));
243	        rollup.changed(sheetId, user, before);
244	        return claim.getPersonId();
245	    }
246	
247	    /**
248	     * Reject a PENDING claim with a reason, putting it back to OPEN (bound again by the last statement if
249	     * that statement counted it). Only a steward rejects; a claim not PENDING or dated inside a closed
250	     * period is refused and nothing changes. Returns the person it belongs to.
251	     */
252	    @Transactional
253	    public long reject(String sheetId, String user, long claimId, String reason) {
254	        Claim claim = pending(sheetId, user, claimId, "reject", "rejected");
255	        Rollup.Figures before = rollup.figures(sheetId);
256	        claim.setStatus(ClaimStatus.OPEN);
257	        Person owner = people.findByIdAndSheetId(claim.getPersonId(), sheetId).orElse(null);
258	        log(sheetId, user, claim, owner);
259	        claims.flush();
260	        String person = owner == null ? "" : owner.getName();
261	        events.publishEvent(new ClaimChanged("CLAIM_REJECTED", sheetId, user, person, claim.getAmount(),
262	                claim.getDate(), claim.getShownNumber(), null, reason));
263	        rollup.changed(sheetId, user, before);
264	        return claim.getPersonId();
265	    }
266	
267	    /**
268	     * A steward moves a DRAFT, OPEN or PENDING claim to another person on the sheet. The claim keeps its
269	     * number and date, is released from any figure a statement bound it to (live again until its new
270	     * person's next statement), and lists as its new person's newest claim. A settled or voided claim, a
271	     * correction, a claim dated inside a closed period or after the new person's retirement date, or a move
272	     * by anyone but a steward is refused and nothing changes. Returns the people it moved from and to.
273	     */
274	    @Transactional
275	    public long[] reassign(String sheetId, String user, long claimId, long toPersonId) {
276	        Claim claim = claim(sheetId, claimId);
277	        if (access.roleOf(sheetId, user) != Role.STEWARD) {
278	            throw new ResponseStatusException(HttpStatus.CONFLICT, "Only a steward can reassign a claim");
279	        }
280	        if (claim.getStatus() != ClaimStatus.DRAFT && claim.getStatus() != ClaimStatus.OPEN
281	                && claim.getStatus() != ClaimStatus.PENDING) {
282	            throw new ResponseStatusException(HttpStatus.CONFLICT,
283	                    "A " + claim.getStatus() + " claim cannot be reassigned");
284	        }
285	        if (claim.isCorrection()) {
286	            throw new ResponseStatusException(HttpStatus.CONFLICT,
287	                    "A correction belongs with the claim it corrects and cannot be reassigned");
288	        }
289	        Person from = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
290	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person"));
291	        Person to = people.findByIdAndSheetId(toPersonId, sheetId)
292	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.CONFLICT, "Choose a person on the sheet"));
293	        if (from.getId().equals(to.getId())) {
294	            throw new ResponseStatusException(HttpStatus.CONFLICT, "The claim is already " + to.getName() + "'s");
295	        }
296	        requireNotRetired(to, claim.getDate());
297	        Rollup.Figures before = rollup.figures(sheetId);
298	        claim.setPersonId(to.getId());
299	        claim.unbind();
300	        claims.flush();
301	        claims.relist(claim.getId());
302	        events.publishEvent(new ClaimReassigned(sheetId, user, to.getName(), claim.getAmount(), claim.getDate(),
303	                claim.getShownNumber(), from.getName(), to.getName()));
304	        rollup.changed(sheetId, user, before);
305	        return new long[] { from.getId(), to.getId() };
306	    }
307	
308	    /** The PENDING claim a steward is to approve or reject; refused for anyone else or any other claim. */
309	    private Claim pending(String sheetId, String user, long claimId, String action, String done) {
310	        Claim claim = claim(sheetId, claimId);
311	        if (claim.getStatus() != ClaimStatus.PENDING) {
312	            throw new ResponseStatusException(HttpStatus.CONFLICT,
313	                    "A " + claim.getStatus() + " claim cannot be " + done + "; only a PENDING one can");
314	        }
315	        if (access.roleOf(sheetId, user) != Role.STEWARD) {
316	            throw new ResponseStatusException(HttpStatus.CONFLICT, "Only a steward can " + action + " a claim");
317	        }
318	        return claim;
319	    }
320	
321	    private Claim claim(String sheetId, long claimId) {
322	        Claim claim = claims.findByIdAndSheetId(claimId, sheetId)
323	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim"));
324	        periods.requireOpen(sheetId, claim.getDate());
325	        return claim;
326	    }
327	
328	    /** Log the status a claim has just taken, on the sheet's today, with its due as it is now. */
329	    private void log(String sheetId, String user, Claim claim, Person owner) {
330	        BigDecimal due = owner == null ? (Dues.bound(claim) ? claim.getStatedDue() : claim.getSettledDue())
331	                : Dues.figure(claim, owner::gradeOn, rates.table(sheetId));
332	        claim.logStatus(user, sheets.today(sheetId), due);
333	    }
334	
335	    /** The claim's due now, its late charge frozen in, as settling fixes it. */
336	    private BigDecimal dueNow(String sheetId, Claim claim, Person owner) {
337	        return owner == null ? (Dues.bound(claim) ? claim.getStatedDue() : null)
338	                : Dues.figure(claim, owner::gradeOn, rates.table(sheetId));
339	    }
340	
341	    /**
342	     * Give a claim being opened its number: while the sheet's period numbering from is set and the
343	     * sheet's today is on or after it, the next in the period its date falls in (<period name>-<n>), or
344	     * in the sequence of claims in no period (X-<n>); otherwise the next sheet-wide number. Two users
345	     * taking one at the same moment wait on each other, so no number is given twice or skipped.
346	     */
347	    private void giveNumber(String sheetId, Claim claim) {
348	        LocalDate from = sheets.periodNumberingFrom(sheetId);
349	        if (from == null || sheets.today(sheetId).isBefore(from)) {
350	            claim.setNumber(sheets.nextClaimNumber(sheetId));
351	            return;
352	        }
353	        sheetRows.lockById(sheetId);
354	        Period period = periods.list(sheetId).stream().filter(p -> p.contains(claim.getDate()))
355	                .findFirst().orElse(null);
356	        String sequence = period == null ? "X" : "P" + period.getId();
357	        int n = claims.lastInSequence(sheetId, sequence) + 1;
358	        claim.setPeriodNumber(sequence, n, (period == null ? "X" : period.getName()) + "-" + n);
359	    }
360	
361	    /**
362	     * Refuse a correction (a negative amount) that does not name the number of a SETTLED claim of the
363	     * same person, and a claim that is not a correction but names one. Returns the date of the claim a
364	     * correction corrects (its rounding goes by it); null for any other claim.
365	     */
366	    private LocalDate requireCorrects(String sheetId, long personId, BigDecimal amount, String corrects) {
367	        if (amount.signum() >= 0) {
368	            if (corrects != null) {
369	                throw new ResponseStatusException(HttpStatus.CONFLICT,
370	                        "Only a correction (a negative amount) names a claim it corrects");
371	            }
372	            return null;
373	        }
374	        if (corrects == null) {
375	            throw new ResponseStatusException(HttpStatus.CONFLICT,
376	                    "A negative amount is a correction; name the number of the settled claim it corrects");
377	        }
378	        return claims.findBySheetIdAndPersonIdOrderByIdDesc(sheetId, personId).stream()
379	                .filter(c -> corrects.equals(c.getShownNumber()) && c.getStatus() == ClaimStatus.SETTLED)
380	                .map(Claim::getDate).findFirst()
381	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.CONFLICT,
382	                        "Claim " + corrects + " is not a settled claim of this person"));
383	    }
384	
385	    /** Refuse a claim dated after its person's retirement date. */
386	    private static void requireNotRetired(Person person, LocalDate date) {
387	        if (person.isRetired() && date.isAfter(person.getRetiredFrom())) {
388	            throw new ResponseStatusException(HttpStatus.CONFLICT,
389	                    person.getName() + " is retired from " + person.getRetiredFrom()
390	                            + "; a claim cannot be dated after that");
391	        }
392	    }
393	}
