package net.officefloor.hq.app.claim;

import java.math.BigDecimal;
import java.util.List;
import java.util.Objects;
import net.officefloor.hq.app.rate.Grades;
import net.officefloor.hq.app.rate.RateService;
import net.officefloor.hq.app.rate.RateTable;

/** The due figures of claims and the due-total of a person's claims. */
public final class Dues {

    private Dues() {
    }

    /**
     * A claim's due: once settled, the due fixed then (its late charge frozen in); otherwise its
     * {@link #base} figure plus, while overdue, its {@link RateTable#lateCharge late charge}. Null when there
     * is none.
     */
    public static BigDecimal figure(Claim claim, Grades grades, RateTable rates) {
        if (claim.getSettledDue() != null) {
            return claim.getSettledDue();
        }
        BigDecimal base = base(claim, grades, rates);
        if (base == null || claim.isCorrection() || !overdue(claim, rates)) {
            return base;
        }
        return base.add(rates.lateCharge(base, claim.getDate(), claim.getDueBy(), claim.getRoundsBy()));
    }

    /**
     * A claim's figure before any late charge: while bound by a statement (and not PENDING, which is
     * never bound), the figure bound then;
     * otherwise the amount at the rate in force on its date for its person's grade in force then, but at
     * least the sheet's floor; a correction has no floor and no late charge. Rounded by the date the claim's
     * rounding goes by, see {@link RateTable#rounding}. Null when there is none. A
     * statement binds this figure, never the late charge.
     */
    public static BigDecimal base(Claim claim, Grades grades, RateTable rates) {
        if (bound(claim)) {
            return claim.getStatedDue();
        }
        String grade = grades.on(claim.getDate());
        return claim.isCorrection() ? RateService.due(claim.getAmount(), rates.on(grade, claim.getDate()),
                rates.rounding(claim.getRoundsBy()))
                : rates.due(claim.getAmount(), grade, claim.getDate());
    }

    /**
     * The figure the claim would have today as an OPEN claim bound by no statement: the amount at the rate
     * in force on its date for its person's grade then (at least the sheet's floor, a correction having none),
     * plus the late charge it has today when its due-by has passed (a correction having none). Null when
     * there is none. Re-settling a claim fixes its due at this figure.
     */
    public static BigDecimal asOpen(Claim claim, Grades grades, RateTable rates) {
        String grade = grades.on(claim.getDate());
        BigDecimal base = claim.isCorrection() ? RateService.due(claim.getAmount(), rates.on(grade, claim.getDate()),
                rates.rounding(claim.getRoundsBy()))
                : rates.due(claim.getAmount(), grade, claim.getDate());
        if (base == null || claim.isCorrection() || !claim.getDueBy().isBefore(rates.today())) {
            return base;
        }
        return base.add(rates.lateCharge(base, claim.getDate(), claim.getDueBy(), claim.getRoundsBy()));
    }

    /** Whether a statement binds the claim's figure: it is stated and not PENDING. */
    public static boolean bound(Claim claim) {
        return claim.isStated() && claim.getStatus() != ClaimStatus.PENDING;
    }

    /** Whether the claim is overdue: OPEN or PENDING, and due by a date before the sheet's today (its due-by, fixed when it was added). */
    public static boolean overdue(Claim claim, RateTable rates) {
        return claim.getStatus().unpaid() && claim.getDueBy().isBefore(rates.today());
    }

    /** The overdue claims that count, see {@link #overdue} and {@link #counts}. */
    public static List<Claim> overdue(List<Claim> claims, RateTable rates, Holds holds) {
        return claims.stream().filter(c -> counts(c, holds) && overdue(c, rates)).toList();
    }

    /** The sum of the due figures of the claims given (0.00 with none); a claim with none is skipped. */
    public static BigDecimal sum(Grades grades, List<Claim> claims, RateTable rates) {
        return claims.stream().map(c -> figure(c, grades, rates)).filter(Objects::nonNull)
                .reduce(BigDecimal.ZERO, BigDecimal::add);
    }

    /** Whether the claim's figure is kept whatever the rates: fixed by settling or bound by a statement. */
    private static boolean kept(Claim claim) {
        return claim.getSettledDue() != null || (bound(claim) && claim.getStatedDue() != null);
    }

    /**
     * Whether the claim counts in the live totals: OPEN, PENDING and SETTLED claims do, except that an
     * OPEN claim dated within one of its person's holds counts in none, unless a statement binds it.
     */
    public static boolean counts(Claim claim, Holds holds) {
        return claim.getStatus().counts() && !(claim.getStatus() == ClaimStatus.OPEN && !bound(claim)
                && holds.on(claim.getDate()));
    }

    /**
     * A person's due-total (see {@link #total}); a person not on hold.
     */
    public static BigDecimal total(Grades grades, List<Claim> claims, RateTable rates) {
        return total(grades, claims, rates, Holds.NONE);
    }

    /**
     * A person's due-total: their {@link #uncapped} sum held to the sheet's cap, see {@link RateTable#capped}.
     * Null (n/a) when the sum is.
     */
    public static BigDecimal total(Grades grades, List<Claim> claims, RateTable rates, Holds holds) {
        return rates.capped(uncapped(grades, claims, rates, holds));
    }

    /** What a person's {@link #uncapped} sum is above the sheet's cap: 0.00 when it is not, or is n/a. */
    public static BigDecimal excess(Grades grades, List<Claim> claims, RateTable rates, Holds holds) {
        return rates.excess(uncapped(grades, claims, rates, holds));
    }

    /**
     * The sum of the due figures of the claims that count (0.00 with none), see {@link #counts}. Null (n/a)
     * when the grade in force on the sheet's today has no rate on it, unless a claim that counts has a
     * figure not made by that grade (kept, or at the rate for another grade in force on its date): then it
     * is the sum of the figures there are; so too when that grade's rate has ended by the sheet's today and
     * a claim that counts has a figure.
     */
    public static BigDecimal uncapped(Grades grades, List<Claim> claims, RateTable rates, Holds holds) {
        List<Claim> counting = claims.stream().filter(c -> counts(c, holds)).toList();
        String current = grades.on(rates.today());
        boolean ended = rates.ended(current, rates.today());
        boolean shown = rates.current(current) != null || counting.stream().anyMatch(c -> kept(c)
                || ((ended || !current.equals(grades.on(c.getDate()))) && figure(c, grades, rates) != null));
        return shown ? counting.stream().map(c -> figure(c, grades, rates))
                .filter(Objects::nonNull).reduce(BigDecimal.ZERO, BigDecimal::add) : null;
    }
}
package net.officefloor.hq.app.rollup;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Objects;
import java.util.stream.Collectors;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.ClaimRepository;
import net.officefloor.hq.app.claim.Dues;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.rate.RateRepository;
import net.officefloor.hq.app.rate.RateTable;
import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.hq.app.sheet.DatedSettings;
import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.hq.app.sheet.SheetSettingRepository;
import org.springframework.context.ApplicationEventPublisher;
import org.springframework.stereotype.Service;

/**
 * The figures of a sheet: each person's claimed, due-total and overdue-total, and the sheet's
 * claimed-total, due-total (a person showing n/a is skipped) and overdue-total. A change takes the figures before it and, once done,
 * announces the ones it moved. Reads the store directly, within the change's own transaction.
 */
@Service
public class Rollup {

    /**
     * A person's figures as shown: claimed, due-total ({@code n/a} when there is none), and overdue-total
     * (the sum of the due figures of their overdue claims that count).
     */
    public record PersonFigures(String name, String claimed, String dueTotal, String overdueTotal) {

        boolean sameFigures(PersonFigures other) {
            return other != null && claimed.equals(other.claimed) && dueTotal.equals(other.dueTotal)
                    && overdueTotal.equals(other.overdueTotal);
        }
    }

    /** The sheet's claimed-total, due-total and overdue-total as shown. */
    public record Totals(String claimed, String dueTotal, String overdueTotal) {
    }

    /** Everyone's figures by person id, in the order they were added, and the sheet's totals. */
    public record Figures(Map<Long, PersonFigures> people, Totals totals) {
    }

    private final PersonRepository people;
    private final ClaimRepository claims;
    private final RateRepository rates;
    private final SheetRepository sheets;
    private final SheetSettingRepository settings;
    private final ApplicationEventPublisher events;

    public Rollup(PersonRepository people, ClaimRepository claims, RateRepository rates, SheetRepository sheets,
            SheetSettingRepository settings, ApplicationEventPublisher events) {
        this.settings = settings;
        this.people = people;
        this.claims = claims;
        this.rates = rates;
        this.sheets = sheets;
        this.events = events;
    }

    /** The sheet's figures now. */
    public Figures figures(String sheetId) {
        Sheet sheet = sheets.findById(sheetId).orElse(null);
        LocalDate today = sheet == null ? LocalDate.now() : sheet.getToday();
        RateTable table = new RateTable(rates.findBySheetId(sheetId), today,
                new DatedSettings(settings.findBySheetId(sheetId)), sheet == null ? null : sheet.getPolicyDate());
        Map<Long, List<Claim>> bySheet = claims.findBySheetIdOrderByIdDesc(sheetId).stream()
                .collect(Collectors.groupingBy(Claim::getPersonId));
        Map<Long, PersonFigures> figures = new LinkedHashMap<>();
        BigDecimal claimedTotal = BigDecimal.ZERO;
        BigDecimal dueTotal = BigDecimal.ZERO;
        BigDecimal overdueTotal = BigDecimal.ZERO;
        for (Person person : people.findBySheetIdOrderByIdAsc(sheetId)) {
            List<Claim> theirs = bySheet.getOrDefault(person.getId(), List.of());
            BigDecimal claimed = theirs.stream().filter(c -> Dues.counts(c, person::heldOn)).map(Claim::getAmount)
                    .reduce(BigDecimal.ZERO, BigDecimal::add);
            BigDecimal due = Dues.total(person::gradeOn, theirs, table, person::heldOn);
            BigDecimal overdue = Dues.sum(person::gradeOn, Dues.overdue(theirs, table, person::heldOn), table);
            claimedTotal = claimedTotal.add(claimed);
            overdueTotal = overdueTotal.add(overdue.setScale(2, RoundingMode.HALF_UP));
            if (due != null) {
                dueTotal = dueTotal.add(due);
            }
            figures.put(person.getId(), new PersonFigures(person.getName(), money(claimed),
                    due == null ? "n/a" : money(due), money(overdue)));
        }
        return new Figures(figures, new Totals(money(claimedTotal), money(dueTotal), money(overdueTotal)));
    }

    /**
     * Announce the figures the change moved since {@code before}: each person whose figures changed (one
     * who did not exist before counting as changed), then the totals when they changed. Nothing when no
     * figure moved.
     */
    public void changed(String sheetId, String user, Figures before) {
        Figures after = figures(sheetId);
        List<PersonFigures> moved = new ArrayList<>();
        after.people().forEach((id, now) -> {
            if (!now.sameFigures(before.people().get(id))) {
                moved.add(now);
            }
        });
        Totals totals = Objects.equals(before.totals(), after.totals()) ? null : after.totals();
        if (!moved.isEmpty() || totals != null) {
            events.publishEvent(new RollupChanged(sheetId, user, moved, totals));
        }
    }

    private static String money(BigDecimal amount) {
        return amount.setScale(2, RoundingMode.HALF_UP).toPlainString();
    }
}
package net.officefloor.hq.app.claim;

/**
 * A claim's status: it starts as DRAFT, is opened (OPEN) and then settled (SETTLED); a clerk settling
 * one above the clerk limit leaves it PENDING until a steward approves it (SETTLED) or rejects it (back to
 * OPEN). A DRAFT, OPEN or PENDING claim can be voided (VOID). Only OPEN, PENDING and SETTLED claims count
 * toward what is claimed.
 */
public enum ClaimStatus {
    DRAFT, OPEN, PENDING, SETTLED, VOID;

    /** Whether the claim counts toward claimed, due-total and every total. */
    public boolean counts() {
        return this == OPEN || this == PENDING || this == SETTLED;
    }

    /** Whether the claim is still to be paid: OPEN or PENDING. */
    public boolean unpaid() {
        return this == OPEN || this == PENDING;
    }

    /**
     * Whether a claim in this status may be moved to the given one by opening, settling or voiding it; a
     * PENDING claim leaves PENDING only by being approved, rejected or voided.
     */
    public boolean canBecome(ClaimStatus next) {
        return switch (next) {
            case OPEN -> this == DRAFT;
            case PENDING, SETTLED -> this == OPEN;
            case VOID -> this == DRAFT || this == OPEN || this == PENDING;
            case DRAFT -> false;
        };
    }
}
package net.officefloor.hq.app.claim;

import java.math.BigDecimal;
import java.time.LocalDate;

/**
 * A claim was added ({@code CLAIM_ADDED}), edited ({@code CLAIM_EDITED}), opened
 * ({@code CLAIM_OPENED}), settled ({@code CLAIM_SETTLED}), left pending ({@code CLAIM_PENDING}), approved
 * ({@code CLAIM_APPROVED}), rejected ({@code CLAIM_REJECTED}) or voided ({@code CLAIM_VOIDED}) on a sheet.
 * The number is the claim's number, or null when it has none. The due is the due fixed by settling or
 * approving ({@code n/a} when there was no rate), or null when the event carries none. The reason is a
 * rejection's reason, or null when the event carries none.
 */
public record ClaimChanged(String event, String sheetId, String user, String person, BigDecimal amount,
        LocalDate date, String number, String due, String reason) {

    public ClaimChanged(String event, String sheetId, String user, String person, BigDecimal amount,
            LocalDate date, String number, String due) {
        this(event, sheetId, user, person, amount, date, number, due, null);
    }
}

