1	import { HttpClient, HttpErrorResponse } from '@angular/common/http';
2	import { Component, computed, inject, input, output, signal } from '@angular/core';
3	import { firstValueFrom } from 'rxjs';
4	import { Session } from '../../core/session';
5	import { Period, periodOf } from '../periods/periods';
6	
7	/**
8	 * DRAFT when added, then OPEN, then SETTLED; a clerk's settle above the clerk limit leaves it PENDING
9	 * until a steward approves it (SETTLED) or rejects it (OPEN again). A steward can re-settle a SETTLED claim,
10	 * fixing its due again at today's figure. A DRAFT, OPEN or PENDING claim can be VOID.
11	 */
12	export type ClaimStatus = 'DRAFT' | 'OPEN' | 'PENDING' | 'SETTLED' | 'VOID';
13	
14	export type ClaimAction = 'open' | 'settle' | 'approve' | 'reject' | 'resettle' | 'void';
15	
16	export interface Claim {
17	  id: number;
18	  amount: string;
19	  date: string;
20	  note: string;
21	  /** The amount at the rate for the person's grade, or once settled the due fixed then; null when there is no rate. */
22	  due: string | null;
23	  status: ClaimStatus;
24	  /** The number the claim got when opened: the next on the sheet, or within its period (P1-1, X-1); null while a draft. */
25	  number: string | null;
26	  /** The user who opened the claim, kept once voided; null while it was never opened. */
27	  openedBy: string | null;
28	  /** Whether the person's last statement binds the claim to the figure it had then. */
29	  stated: boolean;
30	  /** Fixed when the claim was added: its date plus the terms then of its person's grade on its date. */
31	  dueBy: string;
32	  /** Whether the claim is OPEN or PENDING and its due-by is before the sheet's today. */
33	  overdue: boolean;
34	  /** For a correction (a negative amount), the number of the settled claim it corrects, as shown (3, P1-1); null otherwise. */
35	  corrects: string | null;
36	  /** The claim's status log, oldest first: one line per status it has had. */
37	  log: ClaimLogLine[];
38	}
39	
40	/** A line of a claim's status log: the status, who changed it, the sheet's today then and its due then (null when none). */
41	export interface ClaimLogLine {
42	  status: ClaimStatus;
43	  by: string;
44	  on: string;
45	  due: string | null;
46	}
47	
48	/** A hold on a person from a date to a date (both included); null to-date: open-ended. */
49	export interface Hold {
50	  from: string;
51	  to: string | null;
52	}
53	
54	/** Whether the claim is OPEN, not bound by a statement, and dated within one of the holds: it then counts in no live total. */
55	export function heldOut(c: Claim, holds: Hold[]): boolean {
56	  return c.status === 'OPEN' && !c.stated && holds.some((h) => c.date >= h.from && (h.to === null || c.date <= h.to));
57	}
58	
59	export interface PersonWithClaims {
60	  id: number;
61	  /** The version the person was last saved at; an edit sends the one its editor loaded. */
62	  version: number;
63	  name: string;
64	  grade: string;
65	  claims: Claim[];
66	  /** The amounts of the OPEN, PENDING and SETTLED claims added up, but not unbound OPEN ones dated within a hold. */
67	  claimed: string;
68	  /** Claimed at the rate for the person's grade, held to the sheet's cap; null when the grade has no rate. */
69	  dueTotal: string | null;
70	  /** What the person's sum of figures is above the sheet's cap; 0.00 when it is not (or is n/a). */
71	  excess: string;
72	  /** How many statements were taken for the person. */
73	  statementCount: number;
74	  /** The last statement's due-total; null when there is none or it was n/a. */
75	  statedTotal: string | null;
76	  /** The sheet's today when the last statement was taken; null when there is none. */
77	  statementDate: string | null;
78	  /** Whether a retirement date is set: retired at once, whatever the date. */
79	  retired: boolean;
80	  /** The date the person is retired from; no claim dated after it can be added. Null when not retired. */
81	  retiredFrom: string | null;
82	  /** Whether the person has any hold, whatever its dates. */
83	  held: boolean;
84	  /** The person's holds, earliest first: their OPEN claims dated within one, unless bound by a statement,
85	   * count in no live total. */
86	  holds: Hold[];
87	  /** How many of the claims that count are overdue. */
88	  overdueCount: number;
89	  /** The due figures of the overdue claims that count, added up. */
90	  overdueTotal: string;
91	  /** The ids of the people on the sheet the person named as their patrons. */
92	  patrons: number[];
93	}
