95	const AMOUNT = /^-?\d{1,12}(\.\d{1,2})?$/;
96	const NUMBER = /^([1-9]\d{0,8}|.{1,100}-[1-9]\d{0,8})$/;
97	const DATE = /^\d{4}-\d{2}-\d{2}$/;
98	
99	// A person's claims, newest first, and the one form that adds a claim or, once a claim's editor is
100	// opened, edits it. Each claim can be opened, settled, approved, rejected (with a reason), re-settled or voided. A saved or moved claim answers with
101	// the person, which is handed up as `saved`. Each claim can be selected, to be opened together with
102	// the others selected.
103	@Component({
104	  selector: 'app-claims',
105	  template: `
106	    <ul aria-label="Claims">
107	      @for (c of person().claims; track c.id) {
108	        <li [attr.data-testid]="'claim-row-' + c.id">
109	          <input
110	            type="checkbox"
111	            [id]="'claim-select-' + c.id"
112	            data-testid="claim-select"
113	            [checked]="selected().has(c.id)"
114	            (change)="selectToggled.emit({ id: c.id, checked: checked($event) })"
115	          />
116	          <label [for]="'claim-select-' + c.id" class="visually-hidden">Select claim {{ c.amount }} {{ c.date }}</label>
117	          <span data-testid="claim-amount">{{ c.amount }}</span>
118	          <span data-testid="claim-date">{{ c.date }}</span>
119	          <span data-testid="claim-note">{{ c.note }}</span>
120	          <span>Due <span data-testid="claim-due">{{ c.due ?? 'n/a' }}</span></span>
121	          <span>Status <span data-testid="claim-status">{{ c.status }}</span></span>
122	          <span>No. <span data-testid="claim-number">{{ c.number ?? '' }}</span></span>
123	          <span>Opened by <span data-testid="claim-opened-by">{{ c.openedBy ?? '' }}</span></span>
124	          <span>Stated <span data-testid="claim-stated">{{ c.stated ? 'yes' : 'no' }}</span></span>
125	          <span>Period <span data-testid="claim-period">{{ periodName(c) }}</span></span>
126	          <span>Due by <span data-testid="claim-due-by">{{ c.dueBy }}</span></span>
127	          <span>Overdue <span data-testid="claim-overdue">{{ c.overdue ? 'yes' : 'no' }}</span></span>
128	          <span>Corrects <span data-testid="claim-corrects">{{ c.corrects ?? '' }}</span></span>
129	          <ol aria-label="Status log">
130	            @for (l of c.log; track $index) {
131	              <li data-testid="claim-log-line">{{ l.status }} by {{ l.by }} on {{ l.on }} due={{ l.due ?? 'n/a' }}</li>
132	            }
133	          </ol>
134	          <label [for]="'claim-reject-reason-' + c.id">Reject reason</label>
135	          <input
136	            [id]="'claim-reject-reason-' + c.id"
137	            data-testid="claim-reject-reason"
138	            [value]="rejectReasons()[c.id] ?? ''"
139	            (input)="setRejectReason(c.id, value($event))"
140	          />
141	          @for (a of actions; track a.action) {
142	            <button type="button" [attr.data-testid]="'claim-' + a.action" (click)="move(c, a.action)">
143	              {{ a.label }}<span class="visually-hidden"> claim {{ c.amount }} {{ c.date }}</span>
144	            </button>
145	          }
146	          <label [for]="'claim-reassign-to-' + c.id">Reassign to</label>
147	          <select
148	            [id]="'claim-reassign-to-' + c.id"
149	            data-testid="claim-reassign-to"
150	            (change)="setReassignTo(c.id, value($event))"
151	          >
152	            <option value="" [selected]="!reassignTo()[c.id]">Choose a person</option>
153	            @for (o of others(); track o.id) {
154	              <option [value]="o.id" [selected]="reassignTo()[c.id] === '' + o.id">{{ o.name }}</option>
155	            }
156	          </select>
157	          <button type="button" data-testid="claim-reassign" (click)="reassign(c)">
158	            Reassign<span class="visually-hidden"> claim {{ c.amount }} {{ c.date }}</span>
159	          </button>
160	          @if (claimError()?.id === c.id) {
161	            <p role="alert" data-testid="claim-error">{{ claimError()?.message }}</p>
162	          }
163	          <button type="button" data-testid="claim-edit" (click)="edit(c)">
164	            Edit claim<span class="visually-hidden"> {{ c.amount }} {{ c.date }}</span>
165	          </button>
166	          @if (editing() === c.id) {
167	            <button type="button" data-testid="claim-cancel" (click)="reset()">Cancel</button>
168	          }
169	        </li>
170	      }
171	    </ul>
172	    <form (submit)="save($event)" [attr.aria-label]="(editing() === null ? 'Add claim for ' : 'Edit claim for ') + person().name">
173	      <label [for]="fid('amount')">Amount</label>
174	      <input
175	        [id]="fid('amount')"
176	        inputmode="decimal"
177	        data-testid="claim-form-amount"
178	        [value]="amount()"
179	        (input)="amount.set(value($event)); error.set('')"
180	      />
181	      <label [for]="fid('date')">Date</label>
182	      <input
183	        [id]="fid('date')"
184	        type="date"
185	        data-testid="claim-form-date"
186	        [value]="date()"
187	        (input)="date.set(value($event)); error.set('')"
188	      />
189	      <label [for]="fid('note')">Note</label>
190	      <input
191	        [id]="fid('note')"
192	        data-testid="claim-form-note"
193	        [value]="note()"
194	        (input)="note.set(value($event)); error.set('')"
195	      />
196	      <label [for]="fid('corrects')">Corrects claim no.</label>
197	      <input
198	        [id]="fid('corrects')"
199	        inputmode="numeric"
200	        data-testid="claim-form-corrects"
201	        [value]="corrects()"
202	        (input)="corrects.set(value($event)); error.set('')"
203	      />
204	      <button type="submit" data-testid="claim-form-submit">
205	        {{ editing() === null ? 'Add claim' : 'Save claim' }}
206	      </button>
207	      @if (error()) {
208	        <p role="alert" data-testid="claim-form-error">{{ error() }}</p>
209	      }
210	    </form>
211	  `,
212	})
213	export class Claims {
214	  private readonly http = inject(HttpClient);
215	  private readonly session = inject(Session);
216	
217	  readonly person = input.required<PersonWithClaims>();
218	  readonly periods = input<Period[]>([]);
219	  readonly saved = output<PersonWithClaims>();
220	  /** The people on the sheet a claim can be reassigned to. */
221	  readonly people = input<readonly { id: number; name: string }[]>([]);
222	  /** The ids of the claims selected to be opened together. */
223	  readonly selected = input<ReadonlySet<number>>(new Set());
224	  readonly selectToggled = output<{ id: number; checked: boolean }>();
225	
226	  protected readonly amount = signal('');
227	  protected readonly date = signal('');
228	  protected readonly note = signal('');
229	  protected readonly corrects = signal('');
230	  protected readonly editing = signal<number | null>(null);
231	  protected readonly error = signal('');
232	  /** The refusal of the last action taken on a claim's row, shown on that row. */
233	  protected readonly claimError = signal<{ id: number; message: string } | null>(null);
234	  /** The reason typed for rejecting each claim, by claim id. */
235	  protected readonly rejectReasons = signal<Record<number, string>>({});
236	  /** The id of the person chosen to reassign each claim to, by claim id. */
237	  protected readonly reassignTo = signal<Record<number, string>>({});
238	  /** The other people on the sheet, whom this person's claims can be reassigned to. */
239	  protected readonly others = computed(() => this.people().filter((p) => p.id !== this.person().id));
240	  /** A submit or action still waiting for its answer: another press meanwhile is ignored. */
241	  private busy = false;
242	  protected readonly actions: { action: ClaimAction; label: string }[] = [
243	    { action: 'open', label: 'Open' },
244	    { action: 'settle', label: 'Settle' },
245	    { action: 'approve', label: 'Approve' },
246	    { action: 'reject', label: 'Reject' },
247	    { action: 'resettle', label: 'Re-settle' },
248	    { action: 'void', label: 'Void' },
249	  ];
250	
251	  /** The name of the period whose dates contain the claim's date; '' when none does. */
252	  protected periodName(c: Claim): string {
253	    return periodOf(this.periods(), c.date)?.name ?? '';
254	  }
255	
256	  protected setRejectReason(id: number, reason: string): void {
257	    this.rejectReasons.update((all) => ({ ...all, [id]: reason }));
258	    if (this.claimError()?.id === id) this.claimError.set(null);
259	  }
260	
261	  protected setReassignTo(id: number, personId: string): void {
262	    this.reassignTo.update((all) => ({ ...all, [id]: personId }));
263	    if (this.claimError()?.id === id) this.claimError.set(null);
264	  }
265	
266	  /** A steward moves a claim to the chosen person; a refusal shows on the claim's row. */
267	  protected async reassign(c: Claim): Promise<void> {
268	    if (this.busy) return;
269	    this.claimError.set(null);
270	    const sheet = this.session.sheet();
271	    if (!sheet) return;
272	    const to = this.reassignTo()[c.id] ?? '';
273	    if (to === '') {
274	      this.claimError.set({ id: c.id, message: 'Choose the person to reassign the claim to.' });
275	      return;
276	    }
277	    const headers = { 'X-User': this.session.user() ?? '' };
278	    this.busy = true;
279	    try {
280	      const moved = await firstValueFrom(
281	        this.http.post<PersonWithClaims[]>(
282	          `/api/sheets/${encodeURIComponent(sheet)}/claims/${c.id}/reassign`,
283	          { personId: Number(to) },
284	          { headers },
285	        ),
286	      );
287	      if (this.session.sheet() !== sheet) return;
288	      this.reassignTo.update((all) => ({ ...all, [c.id]: '' }));
289	      for (const person of moved) this.saved.emit(person);
290	    } catch (err) {
291	      if (this.session.sheet() !== sheet) return;
292	      const refusal = err instanceof HttpErrorResponse && err.status === 409 ? err.error?.message : undefined;
293	      this.claimError.set({ id: c.id, message: refusal ?? `A ${c.status} claim cannot be reassigned.` });
294	    } finally {
295	      this.busy = false;
296	    }
297	  }
298	
299	  protected fid(field: string): string {
300	    return `claim-${this.person().id}-${field}`;
301	  }
302	
303	  protected value(e: Event): string {
304	    return (e.target as HTMLInputElement).value;
305	  }
306	
307	  protected checked(e: Event): boolean {
308	    return (e.target as HTMLInputElement).checked;
309	  }
310	
311	  /** Open a claim's editor; only a DRAFT can be edited, so any other is refused on its row. */
312	  protected edit(c: Claim): void {
313	    this.claimError.set(null);
314	    if (c.status !== 'DRAFT') {
315	      this.claimError.set({ id: c.id, message: `A ${c.status} claim cannot be edited; void it and add a new one.` });
316	      return;
317	    }
318	    this.editing.set(c.id);
319	    this.amount.set(c.amount);
320	    this.date.set(c.date);
321	    this.note.set(c.note);
322	    this.corrects.set(c.corrects ?? '');
323	    this.error.set('');
324	  }
325	
326	  protected reset(): void {
327	    this.editing.set(null);
328	    this.amount.set('');
329	    this.date.set('');
330	    this.note.set('');
331	    this.corrects.set('');
332	    this.error.set('');
333	  }
334	
335	  protected async save(e: Event): Promise<void> {
336	    e.preventDefault();
337	    if (this.busy) return;
338	    this.error.set('');
339	    const sheet = this.session.sheet();
340	    if (!sheet) return;
341	    const amount = this.amount().trim();
342	    const date = this.date().trim();
343	    const note = this.note();
344	    const corrects = this.corrects().trim();
345	    if (!AMOUNT.test(amount)) {
346	      this.error.set('Enter an amount with up to two decimals; a negative amount is a correction.');
347	      return;
348	    }
349	    if (corrects !== '' && !NUMBER.test(corrects)) {
350	      this.error.set('Enter the number of the claim this corrects, or leave it blank.');
351	      return;
352	    }
353	    if (date !== '' && !DATE.test(date)) {
354	      this.error.set('Enter a date, or leave it blank for today.');
355	      return;
356	    }
357	    const id = this.editing();
358	    const base = `/api/sheets/${encodeURIComponent(sheet)}`;
359	    const body = { amount, date: date === '' ? null : date, note, corrects: corrects === '' ? null : corrects };
360	    const headers = { 'X-User': this.session.user() ?? '' };
361	    this.busy = true;
362	    try {
363	      const person = await firstValueFrom(
364	        id === null
365	          ? this.http.post<PersonWithClaims>(`${base}/people/${this.person().id}/claims`, body, { headers })
366	          : this.http.put<PersonWithClaims>(`${base}/claims/${id}`, body, { headers }),
367	      );
368	      if (this.session.sheet() !== sheet) return;
369	      this.saved.emit(person);
370	      this.reset();
371	    } catch (err) {
372	      if (this.session.sheet() !== sheet) return;
373	      const refusal = err instanceof HttpErrorResponse && err.status === 409 ? err.error?.message : undefined;
374	      this.error.set(refusal ?? (id === null ? 'Could not add the claim.' : 'Could not save the claim.'));
375	    } finally {
376	      this.busy = false;
377	    }
378	  }
379	
380	  /**
381	   * Open, settle, approve, reject, re-settle or void a claim; a change its status does not allow is refused on its
382	   * row, as is a reject without a reason.
383	   */
384	  protected async move(c: Claim, action: ClaimAction): Promise<void> {
385	    if (this.busy) return;
386	    this.claimError.set(null);
387	    const sheet = this.session.sheet();
388	    if (!sheet) return;
389	    const reason = (this.rejectReasons()[c.id] ?? '').trim();
390	    if (action === 'reject' && reason === '') {
391	      this.claimError.set({ id: c.id, message: 'Enter a reason to reject the claim.' });
392	      return;
393	    }
394	    const headers = { 'X-User': this.session.user() ?? '' };
395	    this.busy = true;
396	    try {
397	      const person = await firstValueFrom(
398	        this.http.post<PersonWithClaims>(
399	          `/api/sheets/${encodeURIComponent(sheet)}/claims/${c.id}/${action}`,
400	          action === 'reject' ? { reason } : null,
401	          { headers },
402	        ),
403	      );
404	      if (this.session.sheet() !== sheet) return;
405	      if (action === 'reject') this.rejectReasons.update((all) => ({ ...all, [c.id]: '' }));
406	      this.saved.emit(person);
407	    } catch (err) {
408	      if (this.session.sheet() !== sheet) return;
409	      if (err instanceof HttpErrorResponse && err.status === 403) {
410	        this.claimError.set({ id: c.id, message: `You opened this claim, so another user must ${action} it.` });
